/// <summary>
/// Data area Id
/// </summary>
/// <param name = "_dataAreaId">DataAreaId</param>
/// <returns>DataAreaId</returns>
[DataMember(extendedTypeStr(dataAreaId))]
public str parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    if (!prmIsDefault(_dataAreaId))
    {
        dataAreaId = _dataAreaId;
    }

    return dataAreaId;
}

[DataMember(identifierStr(METCatchWeightOnHandContract))]
public METCatchWeightOnHandContract parmCatchWeightOnHandContract(METCatchWeightOnHandContract _metCatchWeightOnHandContract = metCatchWeightOnHandContract)
{
    if (!prmIsDefault(_metCatchWeightOnHandContract))
    {
        metCatchWeightOnHandContract = _metCatchWeightOnHandContract;
    }
    return metCatchWeightOnHandContract;
}
